import {updateDFPlayerAudio} from './expansion-media.js';
import {EXPANSION_MODULES} from './expansion-hardware.js';
const segments=['M8 0h16l4 3-4 3H8L4 3Z','M28 5v16l-3 3-3-3V8Z','M28 27v16l-6-3V30l3-3Z','M8 44h16l4 3-4 3H8l-4-3Z','M2 27l6 3v10l-6 3Z','M2 5l6 3v13l-3 3-3-3Z','M8 22h16l3 3-3 3H8l-3-3Z'];
let audio;const voices=new Map();
const paperFrames=new Map();
export function expansionScreen(c){const m=EXPANSION_MODULES[c.type],r=m?.display,s=1.35;if(!r)return '';if(c.type==='xpt2046')return `<rect data-exp-touch="${c.id}" x="${r.x*s}" y="${r.y*s}" width="${r.width*s}" height="${r.height*s}" fill="transparent" style="cursor:crosshair;touch-action:none" aria-label="SPI dokunmatik panel"/>`;if(c.type==='epaper')return `<foreignObject x="${r.x*s}" y="${r.y*s}" width="${r.width*s}" height="${r.height*s}" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" data-exp-paper="${c.id}" width="128" height="296" style="width:100%;height:100%;image-rendering:pixelated;background:#e8ece4" aria-label="E-paper canlı ekran"></canvas></foreignObject>`;return '';}
export function updateExpansionPaper(states){for(const[id,d]of Object.entries(states))if(d.frame)paperFrames.set(id,d);for(const canvas of document.querySelectorAll('[data-exp-paper]')){const d=paperFrames.get(canvas.dataset.expPaper),key=d?.revision??-1;if(canvas.dataset.revision===String(key))continue;canvas.dataset.revision=key;const ctx=canvas.getContext('2d'),im=ctx.createImageData(128,296);for(let n=0;n<128*296;n++){const v=!d||((d.frame[n>>3]>>(7-(n&7)))&1)?231:28;im.data.set([v,v,v,255],n*4);}ctx.putImageData(im,0,0);}}
export function enableExpansionAudio(){audio??=new AudioContext();audio.resume();}
export function expansionDisplay(c){const m=EXPANSION_MODULES[c.type];if(!m||m.kind==='lcd'||m.kind==='button')return '';const w=m.width,h=m.height,s=1.35;let body='';if(m.kind==='segment'){const n=c.type==='segment4'?4:1;body=Array.from({length:n},(_,i)=>`<g transform="translate(${w/2-n*19+i*38} 23)">${segments.map((d,b)=>`<path data-exp-led="${c.id}:${i}:${'ABCDEFG'[b]}" d="${d}" fill="#351a20"/>`).join('')}<circle data-exp-led="${c.id}:${i}:DP" cx="32" cy="47" r="2.5" fill="#351a20"/></g>`).join('');}else if(m.kind==='bar')body=Array.from({length:10},(_,i)=>`<rect data-exp-led="${c.id}:${i}" x="${w/2-55+i*11}" y="26" width="8" height="36" rx="2" fill="#351a20"/>`).join('');else if(m.kind==='rgb')body=`<circle data-exp-rgb="${c.id}" cx="${w/2}" cy="43" r="19" fill="#343d48"/>`;else body=`<text data-exp-value="${c.id}" x="${w/2}" y="${m.valueDisplay?.y??29}" text-anchor="middle" fill="#c6fbef" font-family="Consolas,monospace" font-size="9">—</text>`;return `<g transform="scale(${s})" pointer-events="none">${body}</g>`+expansionScreen(c);}
export function updateExpansion(project,packet,sim){const states={...packet.i2c?.modules,...packet.expansionUART?.modules,...packet.expansion?.modules,...packet.dc?.peripherals?.expansionUART?.modules,...packet.dc?.peripherals?.expansion?.modules},leds=sim.dc?.ledResults||new Map();updateExpansionPaper(states);updateDFPlayerAudio(project,states,sim.running);for(const node of document.querySelectorAll('[data-exp-led]')){const x=leds.get(node.dataset.expLed);node.setAttribute('fill',(x?.averageCurrent??x?.current??0)>.00001?'#ff4e65':'#351a20');}for(const node of document.querySelectorAll('[data-exp-rgb]')){const id=node.dataset.expRgb,values=['R','G','B'].map(p=>Math.round(Math.min(1,Math.max(0,(leds.get(id+':'+p)?.averageCurrent??leds.get(id+':'+p)?.current??0)/.01))*255));node.setAttribute('fill',`rgb(${values.join(',')})`);}for(const node of document.querySelectorAll('[data-exp-value]')){const d=states[node.dataset.expValue];node.textContent=!d?'—':['mfrc522','pn532'].includes(d.type)?d.present?'UID '+(d.uid||[]).map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase():'NO CARD':d.type==='dfplayer'?(d.playing?'PLAY ':'STOP ')+d.track+' / '+d.trackCount:Number.isFinite(d.rpm)?d.rpm.toFixed(0)+' RPM':Number.isFinite(d.angle)?d.angle.toFixed(1)+'°':d.frequency?Math.round(d.frequency)+' Hz':d.on===false?'OFF':d.code!==undefined?'CODE '+d.code:d.samples!==undefined?d.samples+' SAMPLE':d.time||d.kind||('REV '+(d.revision??0));}if(audio){const ids=new Set();for(const[id,d]of Object.entries(states))if(['buzzerActive','buzzerPassive'].includes(d.type)&&d.on&&sim.running&&d.frequency>20&&d.frequency<20000){ids.add(id);if(!voices.has(id)){const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='square';gain.gain.value=.025;oscillator.connect(gain).connect(audio.destination);oscillator.start();voices.set(id,{oscillator,gain});}voices.get(id).oscillator.frequency.value=d.frequency;}for(const[id,v]of voices)if(!ids.has(id)){v.oscillator.stop();voices.delete(id);}}}
